-- # Each parameter of each routine in ROUTINES, ordered by its ordinal position
-- # (6.31, Description, 1 and 2). Every parameter is an unnamed IN parameter
-- # (Description, 4 and 7.b). Its data type is described like the data type of
-- # a column, and is identified by its ordinal position.
SELECT * FROM information_schema.parameters WHERE specific_name = 'GCD_1';
-- SPECIFIC_CATALOG: :memory: SPECIFIC_SCHEMA: VSQL SPECIFIC_NAME: GCD_1 ORDINAL_POSITION: 1 PARAMETER_MODE: IN IS_RESULT: NO AS_LOCATOR: NO PARAMETER_NAME: NULL FROM_SQL_SPECIFIC_CATALOG: NULL FROM_SQL_SPECIFIC_SCHEMA: NULL FROM_SQL_SPECIFIC_NAME: NULL TO_SQL_SPECIFIC_CATALOG: NULL TO_SQL_SPECIFIC_SCHEMA: NULL TO_SQL_SPECIFIC_NAME: NULL DATA_TYPE: SMALLINT CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_OCTET_LENGTH: NULL CHARACTER_SET_CATALOG: NULL CHARACTER_SET_SCHEMA: NULL CHARACTER_SET_NAME: NULL COLLATION_CATALOG: NULL COLLATION_SCHEMA: NULL COLLATION_NAME: NULL NUMERIC_PRECISION: 16 NUMERIC_PRECISION_RADIX: 2 NUMERIC_SCALE: 0 DATETIME_PRECISION: NULL INTERVAL_TYPE: NULL INTERVAL_PRECISION: NULL UDT_CATALOG: NULL UDT_SCHEMA: NULL UDT_NAME: NULL SCOPE_CATALOG: NULL SCOPE_SCHEMA: NULL SCOPE_NAME: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 1
-- SPECIFIC_CATALOG: :memory: SPECIFIC_SCHEMA: VSQL SPECIFIC_NAME: GCD_1 ORDINAL_POSITION: 2 PARAMETER_MODE: IN IS_RESULT: NO AS_LOCATOR: NO PARAMETER_NAME: NULL FROM_SQL_SPECIFIC_CATALOG: NULL FROM_SQL_SPECIFIC_SCHEMA: NULL FROM_SQL_SPECIFIC_NAME: NULL TO_SQL_SPECIFIC_CATALOG: NULL TO_SQL_SPECIFIC_SCHEMA: NULL TO_SQL_SPECIFIC_NAME: NULL DATA_TYPE: SMALLINT CHARACTER_MAXIMUM_LENGTH: NULL CHARACTER_OCTET_LENGTH: NULL CHARACTER_SET_CATALOG: NULL CHARACTER_SET_SCHEMA: NULL CHARACTER_SET_NAME: NULL COLLATION_CATALOG: NULL COLLATION_SCHEMA: NULL COLLATION_NAME: NULL NUMERIC_PRECISION: 16 NUMERIC_PRECISION_RADIX: 2 NUMERIC_SCALE: 0 DATETIME_PRECISION: NULL INTERVAL_TYPE: NULL INTERVAL_PRECISION: NULL UDT_CATALOG: NULL UDT_SCHEMA: NULL UDT_NAME: NULL SCOPE_CATALOG: NULL SCOPE_SCHEMA: NULL SCOPE_NAME: NULL MAXIMUM_CARDINALITY: NULL DTD_IDENTIFIER: 2

-- # A character string parameter can have any length.
SELECT ordinal_position, data_type, character_maximum_length, numeric_precision FROM information_schema.parameters WHERE specific_name = 'SPLIT_PART_1';
-- ORDINAL_POSITION: 1 DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 NUMERIC_PRECISION: NULL
-- ORDINAL_POSITION: 2 DATA_TYPE: CHARACTER VARYING CHARACTER_MAXIMUM_LENGTH: 10485760 NUMERIC_PRECISION: NULL
-- ORDINAL_POSITION: 3 DATA_TYPE: BIGINT CHARACTER_MAXIMUM_LENGTH: NULL NUMERIC_PRECISION: 64

-- # A routine without parameters, such as PI, has no rows. Every parameter
-- # belongs to a routine in ROUTINES.
SELECT COUNT(*) FROM information_schema.parameters WHERE specific_name = 'PI_1';
SELECT COUNT(*) FROM information_schema.parameters AS p WHERE NOT EXISTS (SELECT * FROM information_schema.routines AS r WHERE r.specific_name = p.specific_name);
-- COL1: 0
-- COL1: 0

-- # The short name view PARAMETERS_S has the same rows (5.77).
SELECT specific_name, ordinal_position, from_sql_spec_cat, to_sql_spec_name, char_max_length, numeric_prec_radix, max_cardinality FROM information_schema.parameters_s WHERE specific_name = 'SPLIT_PART_1';
